/* Reads one UTF-8 character.  Returns the bytes it takes (at least 1) and stores
 * its code point; bytes that are not a well-formed character count as one
 * NUML_OVERLAY_NOT_A_CHAR.  The terminating '\0' is not a continuation byte, so a
 * character cut short by the end of the string never reads past it. */
static uint32_t NuML_Overlay_DecodeUtf8(const uint8_t *pu8Text, uint32_t *pu32CodePoint)
{
    uint8_t u8Lead = pu8Text[0];
    uint32_t u32Length;
    uint32_t u32Smallest;   /* a smaller value was encoded longer than it needs */
    uint32_t u32Value;
    uint32_t i;

    if (u8Lead < 0x80u)
    {
        *pu32CodePoint = u8Lead;
        return 1u;
    }

    *pu32CodePoint = NUML_OVERLAY_NOT_A_CHAR;

    if ((u8Lead & 0xE0u) == 0xC0u)
    {
        u32Length = 2u;
        u32Smallest = 0x80u;
        u32Value = u8Lead & 0x1Fu;
    }
    else if ((u8Lead & 0xF0u) == 0xE0u)
    {
        u32Length = 3u;
        u32Smallest = 0x800u;
        u32Value = u8Lead & 0x0Fu;
    }
    else if ((u8Lead & 0xF8u) == 0xF0u)
    {
        u32Length = 4u;
        u32Smallest = 0x10000u;
        u32Value = u8Lead & 0x07u;
    }
    else
    {
        return 1u;      /* a continuation byte, or 0xF8..0xFF, with nothing to lead it */
    }

    for (i = 1u; i < u32Length; i++)
    {
        uint8_t u8Next = pu8Text[i];

        if ((u8Next & 0xC0u) != 0x80u)
        {
            return i;   /* cut short: what was read is one broken character */
        }

        u32Value = (u32Value << 6) | (uint32_t)(u8Next & 0x3Fu);
    }

    if ((u32Value >= u32Smallest) && (u32Value <= 0x10FFFFu)
            && ((u32Value < 0xD800u) || (u32Value > 0xDFFFu)))
    {
        *pu32CodePoint = u32Value;
    }

    return u32Length;
}

/* Index of u32CodePoint in the label glyph table, or -1.  The table is four weak
 * references (see numl_overlay.h): unless Model/Labels.cpp defines all of them
 * there is no table, and every character outside ASCII is drawn as '?'. */
static int32_t NuML_Overlay_FindLabelGlyph(uint32_t u32CodePoint)
{
    uint32_t u32Low = 0u;
    uint32_t u32High = 0u;

    if ((&g_u32LabelGlyphCount != NULL) && (g_au32LabelGlyphCodePoints != NULL)
            && (g_au8LabelGlyphWidths != NULL) && (g_au16LabelGlyphRows != NULL))
    {
        u32High = g_u32LabelGlyphCount;
    }

    while (u32Low < u32High)
    {
        uint32_t u32Mid = u32Low + ((u32High - u32Low) / 2u);
        uint32_t u32At = g_au32LabelGlyphCodePoints[u32Mid];

        if (u32At == u32CodePoint)
        {
            return (int32_t)u32Mid;
        }

        if (u32At < u32CodePoint)
        {
            u32Low = u32Mid + 1u;
        }
        else
        {
            u32High = u32Mid;
        }
    }

    return -1;
}

void NuML_Overlay_DrawText565(void *pvFrameBuffer,
                              uint32_t u32Width,
                              uint32_t u32Height,
                              uint32_t u32X,
                              uint32_t u32Y,
                              const char *szText)
{
    uint16_t *pu16Frame = (uint16_t *)pvFrameBuffer;
    const uint8_t *pu8Text = (const uint8_t *)szText;
    uint32_t u32Col = u32X;

    if ((pu16Frame == NULL) || (szText == NULL))
    {
        return;
    }

    while (*pu8Text != '\0')
    {
        uint32_t u32CodePoint;
        uint32_t u32GlyphW = NUML_OVERLAY_GLYPH_W;
        int32_t i32Glyph = -1;              /* >= 0: drawn from the label glyph table */
        const uint8_t *pu8Narrow = NULL;    /* 8 pixels: a row is one byte */
        const uint16_t *pu16Wide = NULL;    /* up to 16: a row is bit 15 first */
        uint32_t u32Row;

        pu8Text += NuML_Overlay_DecodeUtf8(pu8Text, &u32CodePoint);

        if ((u32CodePoint < NUML_OVERLAY_FIRST_CHAR) || (u32CodePoint > NUML_OVERLAY_LAST_CHAR))
        {
            i32Glyph = NuML_Overlay_FindLabelGlyph(u32CodePoint);

            if (i32Glyph < 0)
            {
                u32CodePoint = (uint32_t)'?';
            }
        }

        if (i32Glyph >= 0)
        {
            u32GlyphW = g_au8LabelGlyphWidths[i32Glyph];
            pu16Wide = &g_au16LabelGlyphRows[(uint32_t)i32Glyph * NUML_OVERLAY_GLYPH_H];

            if (u32GlyphW > NUML_OVERLAY_WIDE_W)
            {
                u32GlyphW = NUML_OVERLAY_WIDE_W;
            }
        }
        else
        {
            pu8Narrow = &s_au8Font8x16[(u32CodePoint - NUML_OVERLAY_FIRST_CHAR) * NUML_OVERLAY_GLYPH_H];
        }

        /* Clip instead of wrapping: a wrapped line on a video frame is worse
         * than a truncated one.  Written without an addition, which would wrap
         * around for a column near UINT32_MAX and let the glyph through. */
        if ((u32Col > u32Width) || (u32GlyphW > (u32Width - u32Col)))
        {
            break;
        }

        for (u32Row = 0u; u32Row < NUML_OVERLAY_GLYPH_H; u32Row++)
        {
            uint32_t u32PixelY = u32Y + u32Row;
            uint16_t u16Bits;
            uint32_t u32Bit;

            if (u32PixelY >= u32Height)
            {
                break;
            }

            u16Bits = (i32Glyph >= 0) ? pu16Wide[u32Row]
                      : (uint16_t)((uint16_t)pu8Narrow[u32Row] << 8);

            for (u32Bit = 0u; u32Bit < u32GlyphW; u32Bit++)
            {
                uint16_t u16Colour = (u16Bits & (uint16_t)(0x8000u >> u32Bit))
                                     ? NUML_OVERLAY_FG : NUML_OVERLAY_BG;

                pu16Frame[(u32PixelY * u32Width) + u32Col + u32Bit] = u16Colour;
            }
        }

        u32Col += u32GlyphW;
    }
}
